mapper.select:
SELECT COUNT(*) AS totalCount, SUM(CASE WHEN auth_status = '已授权' THEN 1 ELSE 0 END) AS authCount, SUM(CASE WHEN auth_status = '已过期' THEN 1 ELSE 0 END) AS expiredCount, SUM(CASE WHEN auth_status = '未授权' THEN 1 ELSE 0 END) AS unAuthCount FROM face_mgmt WHERE deleted = FALSE
AND create_time >= #{startTime}
AND create_time <= #{endTime}

SELECT access_area AS area, COUNT(*) AS count FROM face_mgmt WHERE deleted = FALSE
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY access_area ORDER BY count DESC

SELECT DATE_FORMAT(last_access_time, '%H:00') AS time, COUNT(*) AS count FROM face_mgmt WHERE deleted = FALSE AND last_access_time IS NOT NULL
AND last_access_time >= #{startTime}
AND last_access_time <= #{endTime}
GROUP BY DATE_FORMAT(last_access_time, '%H:00') ORDER BY time
